contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 _value) public {
        uint256 _before = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool _reverted;
        c.burn(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            _reverted = true;
        } else {
            _reverted = false;
        }

        uint256 _after = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert((_reverted && _after == _before) || (!_reverted && _after == _before - _value));
    }
}

