pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 _value) internal {
        uint256 _before;
        try c.totalSupply() returns (uint256 __r) { _before = __r; } catch { return; }
        bool _reverted;
        try c.burn(_value) {
            _reverted = false;
        } catch {
            _reverted = true;
        }
        uint256 _after;
        try c.totalSupply() returns (uint256 __r) { _after = __r; } catch { return; }
        assertTrue((_reverted && _after == _before) || (!_reverted && _after == _before - _value));
    }

    function testFuzz_run(uint256 _value) public {
        _run(_value);
    }

    receive() external payable {}
}
